se cannabis businesses.',source_snapshot_sha256='964d253e5fcd8c95847158aca7f82d96c173f31272f5b376d54f7c4839946430',verified_at=now(),expires_at=now()+interval '30 days',active=true where evidence_key='ncsl-us-md-20260831'; update public.regulatory_market_access_evidence set tier='medical_limited_trade',authority_name='Government of The Bahamas / Cannabis Authority framework',authority_url='https://opm.gov.bs/cannabis-bahamas/',rationale='The official Bahamas government cannabis framework describes medical, scientific and religious cannabis licensing, including cultivation, retail, manufacturing, testing and transport, while the 2024 regulations establish authorisations for import/export. This supports a regulated medical/scientific commercial pathway rather than unrestricted adult-use access.',source_snapshot_sha256='2bbf701dc9687f420bb0347a9034d8d4dd9da44546e53166a2e253f8ef2eafa8',verified_at=now(),expires_at=now()+interval '30 days',active=true where evidence_key='hv-mkt-complete-bs-20260913'; select api.refresh_verified_market_access_tiers('bind-fresh-authority-evidence-20260923') as refreshed;
